import { inspectAnalysisView } from "../application/analysisView/AnalysisViewService.js";
import { toolContract } from "../contracts/toolContracts.js";
import { logToolExecution } from "./toolLogging.js";
import { toolRegistrationOptions } from "./toolRegistrationOptions.js";
/** Bind selected-view projection to its named contract and session Evidence owner. */
export const registerAnalysisViewTool = (server, logger, evidenceById, recordEvidence) => {
    const contract = toolContract("inspect_analysis_view");
    server.registerTool(contract.name, toolRegistrationOptions(contract), async (input) => {
        const result = await logToolExecution(logger, contract.name, () => Promise.resolve(inspectAnalysisView(input, evidenceById)));
        if (!result.ok)
            return server.delivery.toCallToolResult(result, contract);
        const recorded = recordEvidence?.(result.value);
        return server.delivery.toEvidenceToolResult(result.value, contract, recorded);
    });
};
